<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'||getenv('DB_DATABASE')!=='gunindex_rebuild_test')exit(2);
require_once __DIR__.'/../config/bootstrap.php';
$passed=0;
function chat_check(bool $ok):void{if(!$ok)throw new RuntimeException('Chat assertion failed.');}
function chat_reject(callable $run):void{try{$run();}catch(DomainException|InvalidArgumentException|RuntimeException $e){return;}throw new LogicException('Expected chat rejection.');}
function chat_test(string $name,callable $run):void{global$passed;try{$run();++$passed;echo 'PASS '.$name.PHP_EOL;}catch(Throwable $e){fwrite(STDERR,'FAIL '.$name.' ('.get_class($e).' at '.basename($e->getFile()).':'.$e->getLine().")\n");exit(1);}}
function chat_user(PDO $pdo):array{$name='test_'.bin2hex(random_bytes(8));$password='Synthetic chat '.bin2hex(random_bytes(16));$pdo->prepare("INSERT INTO users(username,email,password_hash,full_name,zip,city) VALUES (?,?,?,'Synthetic chat fixture','10115','Testort')")->execute([$name,$name.'@example.invalid',auth_hash($password)]);return['id'=>(int)$pdo->lastInsertId(),'username'=>$name,'password'=>$password];}
function chat_http(CurlHandle $curl,string $path,?array $fields=null):array{curl_setopt($curl,CURLOPT_URL,'http://127.0.0.1:8081'.$path);if($fields===null)curl_setopt($curl,CURLOPT_HTTPGET,true);else{curl_setopt($curl,CURLOPT_POST,true);curl_setopt($curl,CURLOPT_POSTFIELDS,http_build_query($fields));}$body=curl_exec($curl);chat_check(is_string($body));return[(int)curl_getinfo($curl,CURLINFO_RESPONSE_CODE),$body];}
function chat_token(string $html):string{chat_check(preg_match('/name="csrf_token"\s+value="([a-f0-9]{64})"/',$html,$m)===1);return$m[1];}
chat_test('purpose_separation_nonce_randomness_and_tamper_rejection',static function():void{$plain='Synthetic confidential message';$a=crypto_encrypt('chat',$plain);$b=crypto_encrypt('chat',$plain);chat_check($a!==$b&&!str_contains($a,$plain)&&crypto_decrypt('chat',$a)===$plain);chat_reject(static fn()=>crypto_decrypt('mail',$a));$parts=explode(':',$a);$bytes=base64_decode($parts[2],true);$bytes[25]=chr(ord($bytes[25])^1);chat_reject(static fn()=>crypto_decrypt('chat',$parts[0].':'.$parts[1].':'.base64_encode($bytes)));});
chat_test('previous_key_read_and_rekey_preserve_current_encryption',static function():void{$old=getenv('APP_KEY');$previous=getenv('APP_KEY_PREVIOUS');try{$a=crypto_encrypt('chat','Synthetic rotation');putenv('APP_KEY='.base64_encode(random_bytes(32)));putenv('APP_KEY_PREVIOUS='.$old);chat_check(crypto_decrypt('chat',$a)==='Synthetic rotation');$b=crypto_encrypt('chat','Synthetic rotation');putenv('APP_KEY_PREVIOUS');chat_reject(static fn()=>crypto_decrypt('chat',$a));chat_check(crypto_decrypt('chat',$b)==='Synthetic rotation');}finally{putenv('APP_KEY='.$old);$previous===false?putenv('APP_KEY_PREVIOUS'):putenv('APP_KEY_PREVIOUS='.$previous);}});
chat_test('legacy_prefix_is_never_mistaken_for_an_encrypted_message',static function():void{$plain='gx1:0123456789abcdef:legacy-user-text';chat_check(chat_message_plain($plain,0)===$plain);chat_reject(static fn()=>chat_message_plain($plain,1));chat_reject(static fn()=>chat_message_plain($plain,2));});
$seller=chat_user($pdo);$buyer=chat_user($pdo);$outsider=chat_user($pdo);$category=(int)catalog_categories($pdo)[0]['id'];
$pdo->prepare("INSERT INTO market_listings(seller_id,category_id,title,description,type,price_cents,status,zip,city,country_code) VALUES (?,?,'Synthetic chat desk','An ordinary desk for isolated chat regression tests.','fixed',4500,'active','10115','Testort','DE')")->execute([$seller['id'],$category]);$listing=(int)$pdo->lastInsertId();$message='Synthetic private <img src=x onerror=alert(1)> '.bin2hex(random_bytes(12));$messageId=0;
chat_test('new_messages_are_ciphertext_and_round_trip_for_parties',static function()use($pdo,$seller,$buyer,$listing,$message,&$messageId):void{$messageId=chat_send($pdo,$buyer['id'],$listing,$seller['id'],$message);$q=$pdo->prepare('SELECT message_text,cipher_version FROM market_messages WHERE id=?');$q->execute([$messageId]);$row=$q->fetch();chat_check((int)$row['cipher_version']===1&&!str_contains($row['message_text'],$message));$rows=chat_history($pdo,chat_context($pdo,$seller['id'],$listing,$buyer['id']));chat_check(count($rows)===1&&$rows[0]['message_text']===$message);});
chat_test('third_party_pair_and_empty_or_oversize_messages_are_rejected',static function()use($pdo,$seller,$buyer,$outsider,$listing):void{chat_reject(static fn()=>chat_context($pdo,$outsider['id'],$listing,$buyer['id']));chat_reject(static fn()=>chat_send($pdo,$buyer['id'],$listing,$seller['id'],''));chat_reject(static fn()=>chat_send($pdo,$buyer['id'],$listing,$seller['id'],str_repeat('a',5001)));});
chat_test('two_direction_block_and_own_unblock_enforce_server_side_rules',static function()use($pdo,$seller,$buyer,$listing):void{chat_set_block($pdo,$seller['id'],$listing,$buyer['id'],true);chat_reject(static fn()=>chat_send($pdo,$buyer['id'],$listing,$seller['id'],'Blocked send'));chat_reject(static fn()=>chat_send($pdo,$seller['id'],$listing,$buyer['id'],'Blocked reverse send'));chat_set_block($pdo,$buyer['id'],$listing,$seller['id'],false);chat_check(chat_blocked($pdo,$seller['id'],$buyer['id']));chat_set_block($pdo,$seller['id'],$listing,$buyer['id'],false);chat_check(!chat_blocked($pdo,$seller['id'],$buyer['id']));});
chat_test('archived_listing_keeps_authorized_history_and_stops_new_messages',static function()use($pdo,$seller,$buyer,$listing,$message):void{$pdo->prepare("UPDATE market_listings SET status='archived' WHERE id=?")->execute([$listing]);$ctx=chat_context($pdo,$buyer['id'],$listing,$seller['id']);chat_check(!$ctx['can_send']&&chat_history($pdo,$ctx)[0]['message_text']===$message);chat_reject(static fn()=>chat_send($pdo,$buyer['id'],$listing,$seller['id'],'Archived send'));$pdo->prepare("UPDATE market_listings SET status='active' WHERE id=?")->execute([$listing]);});
chat_test('cursor_pagination_is_stable_and_bounded',static function()use($pdo,$seller,$buyer,$listing):void{$q=$pdo->prepare('INSERT INTO market_messages(listing_id,sender_id,receiver_id,message_text,cipher_version,created_at) VALUES (?,?,?,?,1,UTC_TIMESTAMP()-INTERVAL 2 MINUTE)');$ids=[];for($i=0;$i<57;$i++){$q->execute([$listing,$buyer['id'],$seller['id'],crypto_encrypt('chat','Synthetic page '.$i)]);$ids[]=(int)$pdo->lastInsertId();}$ctx=chat_context($pdo,$seller['id'],$listing,$buyer['id']);$new=chat_history($pdo,$ctx);chat_check(count($new)===50&&$new[0]['id']<$new[49]['id']);$old=chat_history($pdo,$ctx,(int)$new[0]['id']);chat_check(count($old)===8&&$old[7]['id']<$new[0]['id']);$next=chat_history($pdo,$ctx,0,(int)$ids[50],3);chat_check(count($next)===3&&$next[0]['id']===$ids[51]);});
chat_test('chat_http_escapes_html_poll_is_private_and_get_does_not_mark_read',static function()use($pdo,$seller,$buyer,$listing,$message,$messageId):void{$curl=curl_init();curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_PROXY=>'',CURLOPT_TIMEOUT=>15]);try{[$status,$body]=chat_http($curl,'/auth/login.php');chat_check($status===200);[$status]=chat_http($curl,'/auth/login.php',['csrf_token'=>chat_token($body),'login'=>$seller['username'],'password'=>$seller['password']]);chat_check($status===303);$path='/user/chat.php?listing_id='.$listing.'&user_id='.$buyer['id'];[$status,$body]=chat_http($curl,$path.'&before='.($messageId+1));chat_check($status===200&&!str_contains($body,$message)&&str_contains($body,h($message)));$q=$pdo->prepare('SELECT is_read FROM market_messages WHERE id=?');$q->execute([$messageId]);chat_check((int)$q->fetchColumn()===0);[$status]=chat_http($curl,$path,['action'=>'read']);chat_check($status===403);[$status,$json]=chat_http($curl,'/user/chat-updates.php?listing_id='.$listing.'&user_id='.$buyer['id'].'&after='.$messageId);chat_check($status===200&&count(json_decode($json,true,16,JSON_THROW_ON_ERROR)['messages'])===25);[$status]=chat_http($curl,'/user/chat-updates.php?listing_id='.$listing.'&user_id='.$seller['id']);chat_check($status===404);}finally{curl_close($curl);}});
echo 'Crypto and chat checks passed: '.$passed.PHP_EOL;
